/**
 * @brief Tests the buffer_append_n function when buffer_resize fails.
 *
 * This test targets the execution path where:
 * 1. The current buffer capacity (self->len) is insufficient for the append.
 * 2. buffer_resize is called to expand the buffer.
 * 3. buffer_resize fails (due to a simulated memory allocation failure).
 * 4. buffer_append_n returns -1.
 * 5. The original buffer's content and size remain unchanged.
 */
void unit_test_buffer_append_n_resize_failure(void) {
    // Setup: Create a buffer with initial data.
    // helper_create_buffer_from_string("initial") internally calls buffer_new_with_copy,
    // which then calls buffer_new_with_size(strlen("initial")).
    // This results in 2 allocations:
    // 1. malloc for the buffer_t struct itself.
    // 2. calloc for the initial data buffer ("initial\0").
    const char *initial_data = "initial"; // Length 7
    buffer_t *buf = helper_create_buffer_from_string(initial_data);
    TEST_ASSERT_NOT_NULL(buf);
    TEST_ASSERT_EQUAL_STRING(initial_data, buf->data);
    TEST_ASSERT_EQUAL_INT(strlen(initial_data), buffer_length(buf));
    TEST_ASSERT_EQUAL_INT(strlen(initial_data), buffer_size(buf)); // buffer_new_with_size sets len to strlen(str)

    // Inputs for buffer_append_n:
    // A string that, when appended, will exceed the current buffer's allocated size.
    const char *string_to_append = "this_is_a_long_string_that_will_force_a_resize"; // Length 46
    size_t len_to_append = strlen(string_to_append);

    // Verify conditions to trigger the path:
    // 1. Current data length: 7
    // 2. Current allocated size (buf->len): 7 (from buffer_new_with_size(7))
    // 3. Needed size for append: 7 (current) + 46 (to append) = 53
    // Condition `self->len > needed` (7 > 53) is FALSE, so resize will be triggered.
    size_t current_data_len = strlen(buf->data);
    size_t current_allocated_size = buffer_size(buf); // buf->len
    size_t needed_size = current_data_len + len_to_append;

    TEST_ASSERT_TRUE(current_allocated_size <= needed_size); // Ensure resize is necessary

    // CRITICAL: Simulate memory allocation failure for the realloc call inside buffer_resize.
    // `helper_create_buffer_from_string` performed 2 allocations.
    // The `buffer_resize` call will attempt the 3rd allocation (realloc).
    malloc_fail_after(2);

    // Test: Call the function under test
    int

int main() {
    printf("Running unit_test_buffer_append_n_resize_failure...
");
    unit_test_buffer_append_n_resize_failure();
    printf("unit_test_buffer_append_n_resize_failure PASSED
